insert into public.series select * from jsonb_populate_recordset(null::public.series, '[{"id":"ser_the-moonlit-kingdom","slug":"the-moonlit-kingdom","creator_id":"usr_calm-originals","title":"The Moonlit Kingdom","tagline":"Two rival courts. One enchanted night that never quite ends.","description":"In the kingdom of Aurelune, the moon never fully sets. When Princess Seraphine is sent to the silver court of her family''s oldest rivals, she expects cold halls and colder hearts. Instead she finds Corin, a quiet cartographer mapping the paths of falling stars, and a palace where every corridor leads somewhere softer than the last.","genre":"Sleep Romantasy","tags":["romance","royalty","enchanted","slow-burn"],"status":"published","is_official":true,"artwork":{"scene":"kingdom","palette":["#0b1640","#2a2f6b","#c9b8ff","#f6e7b8"],"seed":367092023},"soundscape_id":"snd_soft-wind","content_rating":"all-ages","ai_disclosure":null,"trending_score":98,"popularity":97,"created_at":"2026-08-10T13:33:55.483Z","updated_at":"2026-08-17T13:33:55.483Z","published_at":"2026-08-17T13:33:55.483Z"},{"id":"ser_a-cabin-in-the-pines","slug":"a-cabin-in-the-pines","creator_id":"usr_hana-okafor","title":"A Cabin in the Pines","tagline":"A remote mountain village. A gentle mystery. A kettle always on.","description":"Retired librarian Agnes Thorne moves into a cabin above the village of Larch Hollow, where small mysteries unfold as quietly as the snow. A missing music box, an unsigned letter, a light in the old observatory – each night brings one more gentle puzzle and one more cup of tea.","genre":"Cosy Mystery","tags":["mystery","village","winter","tea"],"status":"published","is_official":false,"artwork":{"scene":"cabin","palette":["#0c1b33","#2c3f5e","#f2c58a","#ffe8c2"],"seed":4269171332},"soundscape_id":"snd_fireplace","content_rating":"all-ages","ai_disclosure":null,"trending_score":91,"popularity":88,"created_at":"2026-08-28T13:33:55.483Z","updated_at":"2026-09-04T13:33:55.483Z","published_at":"2026-09-04T13:33:55.483Z"},{"id":"ser_starlight-express","slug":"starlight-express","creator_id":"usr_marcus-lune","title":"Starlight Express","tagline":"A sleeper train between peaceful planets.","description":"The Starlight Express leaves the station at Halcyon every evening and arrives somewhere new by morning. Conductor Juno Pell walks its quiet carriages, checking tickets, pouring cocoa and pointing out the sights: rings of ice, forests of glass, oceans the colour of lavender.","genre":"Sci-Fi & Space","tags":["space","train","journey","planets"],"status":"published","is_official":false,"artwork":{"scene":"space","palette":["#050b24","#1d1f55","#8bd3ff","#ffd6f5"],"seed":3219193454},"soundscape_id":"snd_space-ambience","content_rating":"all-ages","ai_disclosure":null,"trending_score":89,"popularity":90,"created_at":"2026-07-26T13:33:55.483Z","updated_at":"2026-08-02T13:33:55.483Z","published_at":"2026-08-02T13:33:55.483Z"},{"id":"ser_the-secret-garden-nights","slug":"the-secret-garden-nights","creator_id":"usr_calm-originals","title":"The Secret Garden","tagline":"A walled garden with a new discovery every night.","description":"Behind an ivy-covered door in the grounds of an old manor lies a garden that changes every night. Clara, the new gardener''s apprentice, keeps a journal of what she finds: a pond full of reflected stars, a rose that hums, a path that only appears after rain.","genre":"Magical Worlds","tags":["garden","magic","discovery","nature"],"status":"published","is_official":true,"artwork":{"scene":"garden","palette":["#0d1f2b","#244a46","#f5b8c8","#e6f7c9"],"seed":2495511009},"soundscape_id":"snd_forest-night","content_rating":"all-ages","ai_disclosure":null,"trending_score":86,"popularity":93,"created_at":"2026-06-11T13:33:55.483Z","updated_at":"2026-06-18T13:33:55.483Z","published_at":"2026-06-18T13:33:55.483Z"},{"id":"ser_letters-from-lumen","slug":"letters-from-lumen","creator_id":"usr_elodie-frost","title":"Letters from Lumen","tagline":"A gentle romance, told in letters, in a coastal town.","description":"When Nell inherits her grandmother''s bookshop in the seaside town of Lumen, she finds a bundle of unsent letters tucked into the poetry shelf. Each one is addressed to the lighthouse keeper. And the lighthouse keeper, it turns out, is still there.","genre":"Coastal Romance","tags":["romance","letters","seaside","bookshop"],"status":"published","is_official":false,"artwork":{"scene":"coast","palette":["#0a1a33","#27446b","#ffcf9e","#bfe3ff"],"seed":2476615825},"soundscape_id":"snd_ocean-waves","content_rating":"all-ages","ai_disclosure":null,"trending_score":84,"popularity":85,"created_at":"2026-09-04T13:33:55.483Z","updated_at":"2026-09-11T13:33:55.483Z","published_at":"2026-09-11T13:33:55.483Z"},{"id":"ser_the-floating-library","slug":"the-floating-library","creator_id":"usr_calm-originals","title":"The Floating Library","tagline":"A library that drifts between worlds.","description":"The Floating Library sails between fantastical worlds, lending books to anyone who needs a story. Its librarian, the unflappable Mr. Quill, has catalogued every shelf but one. Each night the library docks somewhere new, and someone comes aboard with a question only a book can answer.","genre":"Magical Worlds","tags":["library","books","worlds","whimsy"],"status":"published","is_official":true,"artwork":{"scene":"library","palette":["#120f2e","#3a2b5e","#f3c77a","#ffe9b8"],"seed":2558021887},"soundscape_id":"snd_fireplace","content_rating":"all-ages","ai_disclosure":null,"trending_score":88,"popularity":91,"created_at":"2026-07-11T13:33:55.483Z","updated_at":"2026-07-18T13:33:55.483Z","published_at":"2026-07-18T13:33:55.483Z"},{"id":"ser_the-lantern-keepers-daughter","slug":"the-lantern-keepers-daughter","creator_id":"usr_iris-vale","title":"The Lantern Keeper''s Daughter","tagline":"She lights the lanterns. He guards the forest border.","description":"Every dusk, Wren lights the lanterns that line the border of the Thornwood. Every dawn, a knight from the forest court extinguishes them. When a lantern refuses to go out, the two finally meet – and find the forest has been waiting for them.","genre":"Sleep Romantasy","tags":["romance","forest","fae","lanterns"],"status":"published","is_official":false,"artwork":{"scene":"forest","palette":["#071a1f","#1b3b3a","#ffc46b","#d6ffe7"],"seed":1890604622},"soundscape_id":"snd_forest-night","content_rating":"all-ages","ai_disclosure":null,"trending_score":82,"popularity":74,"created_at":"2026-09-18T13:33:55.483Z","updated_at":"2026-09-25T13:33:55.483Z","published_at":"2026-09-25T13:33:55.483Z"},{"id":"ser_the-tidewater-inn","slug":"the-tidewater-inn","creator_id":"usr_elodie-frost","title":"The Tidewater Inn","tagline":"An inn at the end of a causeway, open only at low tide.","description":"The Tidewater Inn can only be reached when the tide is out. Its guests arrive with the evening mist and leave before the sea returns. Innkeeper Marguerite keeps the fires lit and the soup warm, and never asks where anyone is going.","genre":"Cosy Mystery","tags":["inn","sea","mystery","cosy"],"status":"published","is_official":false,"artwork":{"scene":"ocean","palette":["#081428","#1f3a5c","#ffd59a","#a8d8ff"],"seed":1657872172},"soundscape_id":"snd_ocean-waves","content_rating":"all-ages","ai_disclosure":null,"trending_score":70,"popularity":72,"created_at":"2026-08-20T13:33:55.483Z","updated_at":"2026-08-27T13:33:55.483Z","published_at":"2026-08-27T13:33:55.483Z"},{"id":"ser_orbit-of-quiet","slug":"orbit-of-quiet","creator_id":"usr_marcus-lune","title":"Orbit of Quiet","tagline":"Life aboard a gentle research station orbiting a sleeping gas giant.","description":"Dr. Ama Reyes is the night-shift botanist aboard Halcyon Station, a research ring orbiting the slow, banded giant Thessaly. While the crew sleeps, she tends the hydroponic gardens, talks with the station''s soft-spoken AI, and watches storms drift across the planet below.","genre":"Sci-Fi & Space","tags":["space station","AI","botany","slow sci-fi"],"status":"published","is_official":false,"artwork":{"scene":"space","palette":["#060a1e","#24224f","#ffb38a","#c7d8ff"],"seed":1144487842},"soundscape_id":"snd_space-ambience","content_rating":"all-ages","ai_disclosure":null,"trending_score":77,"popularity":79,"created_at":"2026-07-01T13:33:55.483Z","updated_at":"2026-07-08T13:33:55.483Z","published_at":"2026-07-08T13:33:55.483Z"},{"id":"ser_the-clockmakers-snow","slug":"the-clockmakers-snow","creator_id":"usr_calm-originals","title":"The Clockmaker''s Snow","tagline":"A winter village where every clock tells a different story.","description":"In the alpine village of Uhrenfeld, the old clockmaker has repaired every clock but his own. As the first snow falls, his apprentice Lotte begins to discover that each clock in the village keeps a memory of the hour it was made.","genre":"Gentle Adventure","tags":["winter","village","clocks","craft"],"status":"published","is_official":true,"artwork":{"scene":"village","palette":["#0a1631","#2b3f66","#ffd28a","#eaf2ff"],"seed":646973258},"soundscape_id":"snd_night-village","content_rating":"all-ages","ai_disclosure":null,"trending_score":74,"popularity":81,"created_at":"2026-05-22T13:33:55.483Z","updated_at":"2026-05-29T13:33:55.483Z","published_at":"2026-05-29T13:33:55.483Z"},{"id":"ser_dunes-of-the-silver-caravan","slug":"dunes-of-the-silver-caravan","creator_id":"usr_sol-ramirez","title":"Dunes of the Silver Caravan","tagline":"A night caravan crossing a desert of singing sand.","description":"Every year the Silver Caravan crosses the Sabra Desert by night, guided by the songs the dunes sing as they cool. Young navigator Tariq joins for the first time, learning to read the stars, the wind and the quiet stories of his fellow travellers.","genre":"Gentle Adventure","tags":["desert","caravan","stars","journey"],"status":"published","is_official":false,"artwork":{"scene":"desert","palette":["#0c1033","#3c2c5c","#ffcf87","#ffe9c4"],"seed":3869688333},"soundscape_id":"snd_soft-wind","content_rating":"all-ages","ai_disclosure":null,"trending_score":79,"popularity":58,"created_at":"2026-09-30T13:33:55.483Z","updated_at":"2026-10-07T13:33:55.483Z","published_at":"2026-10-07T13:33:55.483Z"},{"id":"ser_under-the-northern-lights","slug":"under-the-northern-lights","creator_id":"usr_the-quiet-company","title":"Under the Northern Lights","tagline":"A snow-bound village beneath the aurora.","description":"In the far-north village of Kaldvik, winter means months of night and skies that ripple with green and violet light. Sisters Elin and Saga run the village''s only guesthouse, welcoming travellers who have come to see the aurora and stay for the stillness.","genre":"Nature & Journeys","tags":["aurora","snow","north","village"],"status":"published","is_official":false,"artwork":{"scene":"aurora","palette":["#03101f","#0e2f45","#7dffc8","#c7a6ff"],"seed":3258584374},"soundscape_id":"snd_soft-wind","content_rating":"all-ages","ai_disclosure":null,"trending_score":81,"popularity":77,"created_at":"2026-09-09T13:33:55.483Z","updated_at":"2026-09-16T13:33:55.483Z","published_at":"2026-09-16T13:33:55.483Z"},{"id":"ser_the-glass-city-of-meridia","slug":"the-glass-city-of-meridia","creator_id":"usr_marcus-lune","title":"The Glass City of Meridia","tagline":"A peaceful future city where the night is never dark, only soft.","description":"Meridia is a city of glass towers and hanging gardens, where trams glide silently and the streets glow a gentle blue after midnight. Night-tram driver Kenji Hal carries the city''s late travellers home, one quiet stop at a time.","genre":"Sci-Fi & Space","tags":["future city","tram","night","gentle"],"status":"published","is_official":false,"artwork":{"scene":"city","palette":["#071230","#1b2c5e","#7fe0ff","#ffc6e8"],"seed":1806415629},"soundscape_id":"snd_gentle-rain","content_rating":"all-ages","ai_disclosure":null,"trending_score":72,"popularity":70,"created_at":"2026-08-05T13:33:55.483Z","updated_at":"2026-08-12T13:33:55.483Z","published_at":"2026-08-12T13:33:55.483Z"},{"id":"ser_the-willow-lake-house","slug":"the-willow-lake-house","creator_id":"usr_the-quiet-company","title":"The Willow Lake House","tagline":"A summer house on a still mountain lake.","description":"Every summer, the Ashby family returns to the old house on Willow Lake. This year, grown-up siblings June and Theo come back alone, rowing out at dusk, swimming at night, and remembering the summers that made them who they are.","genre":"Nature & Journeys","tags":["lake","summer","family","nostalgia"],"status":"published","is_official":false,"artwork":{"scene":"lake","palette":["#0b1a36","#2d4870","#ffb48a","#d2f0ff"],"seed":884779146},"soundscape_id":"snd_forest-night","content_rating":"all-ages","ai_disclosure":null,"trending_score":68,"popularity":73,"created_at":"2026-07-21T13:33:55.483Z","updated_at":"2026-07-28T13:33:55.483Z","published_at":"2026-07-28T13:33:55.483Z"},{"id":"ser_the-hearthstone-bakery","slug":"the-hearthstone-bakery","creator_id":"usr_hana-okafor","title":"The Hearthstone Bakery","tagline":"A bakery that opens at midnight for those who can''t sleep.","description":"In a crooked town of cobblestones and chimneys, the Hearthstone Bakery opens its doors at midnight. Baker Rosalind kneads dough and listens to the town''s night-wanderers, each of whom leaves with a warm loaf and a lighter heart.","genre":"Cosy Mystery","tags":["bakery","night","town","comfort"],"status":"published","is_official":false,"artwork":{"scene":"village","palette":["#140f2a","#3b2d4f","#ffbf73","#fff0d1"],"seed":3526416179},"soundscape_id":"snd_night-village","content_rating":"all-ages","ai_disclosure":null,"trending_score":76,"popularity":69,"created_at":"2026-09-21T13:33:55.483Z","updated_at":"2026-09-28T13:33:55.483Z","published_at":"2026-09-28T13:33:55.483Z"},{"id":"ser_the-cloud-shepherd","slug":"the-cloud-shepherd","creator_id":"usr_the-quiet-company","title":"The Cloud Shepherd","tagline":"High in the mountains, someone tends the clouds.","description":"Above the valley of Halde, young Pim inherits the strangest job in the world: shepherding clouds. With a crook, a whistle, and an old dog named Barley, Pim guides the clouds to where the rain is needed and tucks them into the mountain hollows each night.","genre":"Magical Worlds","tags":["mountains","clouds","whimsy","coming of age"],"status":"published","is_official":false,"artwork":{"scene":"aurora","palette":["#0c1838","#3d4f84","#ffd3e6","#e8f1ff"],"seed":1651620444},"soundscape_id":"snd_soft-wind","content_rating":"all-ages","ai_disclosure":null,"trending_score":73,"popularity":66,"created_at":"2026-09-25T13:33:55.483Z","updated_at":"2026-10-02T13:33:55.483Z","published_at":"2026-10-02T13:33:55.483Z"},{"id":"ser_the-salt-and-honey-hotel","slug":"the-salt-and-honey-hotel","creator_id":"usr_elodie-frost","title":"The Salt & Honey Hotel","tagline":"A faded seaside hotel, a summer of slow romance.","description":"Rosa takes a summer job at the Salt & Honey, a once-grand seaside hotel that has seen better days. Between polishing brass and serving afternoon tea, she meets Ellis, the quiet gardener restoring its overgrown terrace.","genre":"Coastal Romance","tags":["romance","hotel","summer","seaside"],"status":"published","is_official":false,"artwork":{"scene":"coast","palette":["#0c1734","#3b4a7a","#ffc79e","#ffe6c9"],"seed":3051739714},"soundscape_id":"snd_ocean-waves","content_rating":"all-ages","ai_disclosure":null,"trending_score":71,"popularity":64,"created_at":"2026-09-27T13:33:55.483Z","updated_at":"2026-10-04T13:33:55.483Z","published_at":"2026-10-04T13:33:55.483Z"},{"id":"ser_the-fox-and-the-firefly-court","slug":"the-fox-and-the-firefly-court","creator_id":"usr_iris-vale","title":"The Fox and the Firefly Court","tagline":"A clever fox, a court of fireflies, and an enchanted meadow.","description":"In a meadow where fireflies hold court each summer night, a clever fox named Sorrel is appointed Royal Advisor. There are disputes to settle, festivals to plan and a very small queen who cannot bear to see anyone sad.","genre":"Magical Worlds","tags":["animals","meadow","fable","summer"],"status":"published","is_official":false,"artwork":{"scene":"forest","palette":["#081a24","#1e3d3f","#fff08a","#d9ffd2"],"seed":3879321900},"soundscape_id":"snd_forest-night","content_rating":"all-ages","ai_disclosure":null,"trending_score":65,"popularity":61,"created_at":"2026-09-11T13:33:55.483Z","updated_at":"2026-09-18T13:33:55.483Z","published_at":"2026-09-18T13:33:55.483Z"},{"id":"ser_voyage-of-the-sleepwhale","slug":"voyage-of-the-sleepwhale","creator_id":"usr_calm-originals","title":"Voyage of the Sleepwhale","tagline":"Riding across a dreaming ocean on the back of a gentle giant.","description":"Once every hundred years the Sleepwhale surfaces and carries a single passenger across the Dreaming Sea. This time it is Ottilie, a lighthouse keeper''s granddaughter, who climbs aboard with a satchel of maps and a jar of honey.","genre":"Gentle Adventure","tags":["ocean","whale","voyage","dreams"],"status":"published","is_official":true,"artwork":{"scene":"ocean","palette":["#05122b","#163a63","#a9e4ff","#ffe4f2"],"seed":4910131},"soundscape_id":"snd_ocean-waves","content_rating":"all-ages","ai_disclosure":null,"trending_score":87,"popularity":84,"created_at":"2026-08-15T13:33:55.483Z","updated_at":"2026-08-22T13:33:55.483Z","published_at":"2026-08-22T13:33:55.483Z"},{"id":"ser_the-observatory-on-wren-hill","slug":"the-observatory-on-wren-hill","creator_id":"usr_the-quiet-company","title":"The Observatory on Wren Hill","tagline":"An astronomer, an old telescope and a sky full of stories.","description":"Retired astronomer Professor Halloway invites the village to his hilltop observatory every clear night. Each visit he points the brass telescope at a different corner of the sky and tells the story of what he sees there.","genre":"Nature & Journeys","tags":["stars","astronomy","storytelling","hills"],"status":"published","is_official":false,"artwork":{"scene":"kingdom","palette":["#060d26","#1c2a57","#e0d2ff","#fff3d6"],"seed":3424117606},"soundscape_id":"snd_night-village","content_rating":"all-ages","ai_disclosure":null,"trending_score":62,"popularity":68,"created_at":"2026-06-21T13:33:55.483Z","updated_at":"2026-06-28T13:33:55.483Z","published_at":"2026-06-28T13:33:55.483Z"},{"id":"ser_the-teahouse-at-the-end-of-the-rain","slug":"the-teahouse-at-the-end-of-the-rain","creator_id":"usr_sol-ramirez","title":"The Teahouse at the End of the Rain","tagline":"A mountain teahouse that only appears during the monsoon.","description":"High on a misty mountain path, a teahouse appears only when it rains. Its keeper, Mei, brews a different tea for every traveller who shelters there, and each cup brings back a memory they had almost forgotten.","genre":"Magical Worlds","tags":["rain","tea","mountains","memory"],"status":"published","is_official":false,"artwork":{"scene":"lake","palette":["#0a1830","#284660","#c9f0d2","#ffe6c4"],"seed":685785742},"soundscape_id":"snd_gentle-rain","content_rating":"all-ages","ai_disclosure":null,"trending_score":78,"popularity":55,"created_at":"2026-10-03T13:33:55.483Z","updated_at":"2026-10-10T13:33:55.483Z","published_at":"2026-10-10T13:33:55.483Z"},{"id":"ser_the-cartographers-apprentice","slug":"the-cartographers-apprentice","creator_id":"usr_iris-vale","title":"The Cartographer''s Apprentice","tagline":"Mapping a gentle, unexplored world one valley at a time.","description":"Ada joins the Royal Cartographic Expedition as its youngest member, tasked with mapping the uncharted Verdant Reach. With an ink-stained notebook and a patient mule named Clementine, she maps rivers, valleys and the quiet villages no one has ever written down.","genre":"Gentle Adventure","tags":["maps","expedition","nature","discovery"],"status":"published","is_official":false,"artwork":{"scene":"lake",